import requests,json,datetime,pathlib
p=pathlib.Path(__file__).parent;rows=json.load(open(p/'candidates.json'));receipts=json.load(open(p/'verification-receipts.json'));cov=json.load(open(p/'coverage.json'));t=datetime.datetime.now(datetime.timezone.utc).isoformat()
entries=[('eng_14','tutorial','https://api.openalex.org/works/W2139212933','https://link.springer.com/article/10.1023/A:1009715923555','A Tutorial on Support Vector Machines for Pattern Recognition','Publisher abstract explicitly calls it a tutorial and explains worked examples, proofs and implementation.'),('eng_15','tutorial','https://api.openalex.org/works/W1964357740','https://link.springer.com/article/10.1023/B:STCO.0000035301.49549.88','A tutorial on support vector regression','Publisher abstract explicitly introduces support vector regression, training algorithms and extensions.'),('eng_16','study_review_protocol','https://api.openalex.org/works/W2907987613','https://cora.ucc.ie/items/ce956de1-87c8-4e83-86df-51f7ad82f106/full','Research Protocol for a Case Study of Crowdsourcing Software Development','Institutional repository identifies a seven-page case study protocol and working paper, with design and replication details.')]
for id,form,u,source,title,basis in entries:
 r=requests.get(u,timeout=20);r.raise_for_status();x=r.json();assert x['title'].lower()==title.lower();receipts.append({'url':u,'retrieved_utc':t,'status':r.status_code,'body':x}); b=x['biblio']; cnt=x['cited_by_count'];isprotocol=form=='study_review_protocol';doi=None if isprotocol else x['doi'].removeprefix('https://doi.org/'); year=2014 if isprotocol else x['publication_year']; venue='University of Limerick, Lero Technical Report Lero-TR-2014-03' if isprotocol else x['primary_location']['source']['display_name'];stable='https://hdl.handle.net/10468/7039' if isprotocol else x['doi'];authors=['Klaas-Jan Stol','Brian Fitzgerald'] if isprotocol else [a['author']['display_name'] for a in x['authorships']]; rows.append(dict(id=id,field='engineering_computing',form_id=form,title=title,authors=authors,year=year,venue=venue,doi=doi,stable_url=stable,volume=b.get('volume'),issue=b.get('issue'),pages='1–7' if isprotocol else '-'.join(filter(None,[b.get('first_page'),b.get('last_page')])) or None,form_basis=basis,form_status='source description verified; full-text writing-model assessment pending',selection_signal_type='citation_count',selection_evidence=f'OpenAlex {cnt} cited-by works on {t}; indicator of scholarly attention only.' if not isprotocol else f'OpenAlex {cnt} cited-by works; selected primarily as a bounded institutional protocol, not as proof of wide readership.',selection_source_url=u,citation_count=cnt,citation_provider='OpenAlex',citation_snapshot=t,verification_status='Exact title matched live OpenAlex record and publisher or institutional source; report DOI omitted because source does not identify it.',verification_sources=[u,source],date_notes='Publisher year verified.' if not isprotocol else 'Repository and report identify 2014; repository file name says 2015.',copy_status='unknown; parent library deduplication required',retrieval_locator=stable,why_this_example=basis,limitations='Description assessed; article or report not downloaded.'))
for c in cov:
 if c['form_id']=='tutorial':c.update(status='three_targets',provided=3,candidate_ids=['eng_01','eng_14','eng_15'],reason='Two explicitly labelled tutorials and one tutorial-like methodological guideline.')
 if c['form_id']=='study_review_protocol':c.update(status='partial_gap',provided=1,candidate_ids=['eng_16'],reason='One bounded institutional case-study protocol; two further notable examples remain unverified.')
for name,obj in [('candidates.json',rows),('coverage.json',cov),('verification-receipts.json',receipts)]:json.dump(obj,open(p/name,'w'),indent=2,ensure_ascii=False)
